from z3 import *

house_count = 2

names = {name: Int(name) for name in ["Eric", "Arnold"]}
nationalities = {nat: Int(nat) for nat in ["dane", "brit"]}

all_vars = list(names.values()) + list(nationalities.values())

solver = Solver()

for var in all_vars:
    solver.add(var >= 1, var <= 2)

solver.add(Distinct(list(names.values())))
solver.add(Distinct(list(nationalities.values())))

solver.add(nationalities["brit"] != 1)
solver.add(names["Arnold"] != 2)

if solver.check() == sat:
    model = solver.model()

