from z3 import *

Name = {n: Int(f"Name_{n}") for n in ["Eric", "Arnold"]}
Cigar = {c: Int(f"Cigar_{c.replace(' ', '_')}") for c in ["prince", "pall mall"]}
Nationality = {n: Int(f"Nationality_{n}") for n in ["dane", "brit"]}
Education = {e: Int(f"Education_{e.replace(' ', '_')}") for e in ["associate", "high school"]}
Car = {c: Int(f"Car_{c.replace(' ', '_')}") for c in ["ford f150", "tesla model 3"]}

solver = Solver()

for category in [Name, Cigar, Nationality, Education, Car]:
    for v in category.values():
        solver.add(v >= 1, v <= 2)
    solver.add(Distinct(*category.values()))

solver.add(Name["Eric"] != 1)
solver.add(Nationality["brit"] == 2)
solver.add(Name["Eric"] == Education["high school"])
solver.add(Cigar["pall mall"] == Nationality["brit"])
solver.add(Car["tesla model 3"] == Cigar["pall mall"])

if solver.check() == sat:
    model = solver.model()

    def find(category, house):
        for attribute, var in category.items():
            if model.eval(var, model_completion=True).as_long() == house:
                return attribute
        raise RuntimeError("missing attribute")

    for house in [1, 2]:
        row = [find(cat, house) for cat in [Name, Cigar, Nationality, Education, Car]]
        print(f"House {house}: " + ", ".join(row))
else:
    print("unsat")
